def parse_integer(text: str) -> int:
    """Convert validated, optionally signed ASCII decimal digits in chunks."""
    negative = text.startswith("-")
    if text[:1] in ("+", "-"):
        text = text[1:]
    value = int(text[:9])
    for start in range(9, len(text), 9):
        chunk = text[start:start + 9]
        value = value * 10 ** len(chunk) + int(chunk)
    return -value if negative else value


def integer_text(value: int) -> str:
    """Render an arbitrary-size integer without unbounded decimal conversion."""
    sign = "-" if value < 0 else ""
    value = abs(value)
    chunks = []
    while value >= 1_000_000_000:
        value, chunk = divmod(value, 1_000_000_000)
        chunks.append(str(chunk).zfill(9))
    chunks.append(str(value))
    return sign + "".join(reversed(chunks))
